<style lang="scss">
  .modal-actions {
    justify-content: space-between;
  }
  .topay {
    text-transform: uppercase;
    background-color: #015a57;
    color: #fff;
    padding: 10px;
    border-radius: 30px;
    &:hover {
      background-color: #014442;
      color: #fff;
    }
  }
  .purchase-slides {

    .slide2 {
    }
    .slides {
      width: 100%;
      margin-bottom: 10px;

      .payment {
        div {
          border: 1px solid #d1d1d1;
          padding: 10px;
          width: -webkit-fill-available;
          font-size: 16px;
          font-family: var(--font-500);
          text-align: center;
          justify-content: center;
          row-gap: 10px;

          span {
            font-size: 13px;
            font-family: var(--font-400);
            color: var(--main-color);
          }
          &.type {
            i {
              height: 30px;
              width: auto;
              svg {
                height: inherit;
                width: 100%;
              }
            }
          }
          &.sum {
            color: #015a57;
          }
        }
      }

      

      .purchase-sum {
        border: 1px solid #d1d1d1;
        padding: 10px;
        justify-content: space-between;
        color: #015a57;
        border-radius: 10px;
        span {
          font-family: var(--font-500);

        }
      }

      form {
        margin-block: 20px;
        .form-title {
          p {
            font-family: var(--font-500);
            color: #015a57;
            margin-block: 10px;
          }
        }
        .forms-payment {
          flex-wrap: wrap;
          gap: 10px;
          .item {
            width: 48%;
            padding-block: 20px;
